arguments.command:
cd /tmp/sv-1ac729c2fe374850a554c54fb8a1afd5
# The 0x2f4* addresses are in .data.rel.ro (interpreter jump table labels)
# These are within mono_interp_exec_method's label array - meaning the thread
# was executing the interpreter main loop. Let me get the proper function context.

# Let me check what's actually a code function before/after these addresses
nm libmonosgen-2.0.so 2>/dev/null | sort | awk -v target="0x2f4b20" '
  { addr = "0x" $1 }
  addr <= target { prev = $0 }
  addr > target && !found { print "Before:", prev; print "After:", $0; found=1 }
' | head -4

