cd /tmp/sv-1ac729c2fe374850a554c54fb8a1afd5
# Check what section 0x2f4b20 falls in
readelf -S libmonosgen-2.0.so 2>/dev/null | grep -E "^\s+\[" | awk '{
  if (NF > 5) {
    name=$2; addr=$4; off=$5; size=$6
    start=strtonum("0x"addr)
    sz=strtonum("0x"size)
    if (start <= 0x2f4b20 && start+sz > 0x2f4b20) print "0x2f4b20 in section", name, "addr:", addr, "size:", size
  }
}'

